function vst_FKfingers_Execute(  )
{
	try
	{
	fingers = SelectObj("*Finger*");
	}
	catch(e)
	{
		logmessage ("No fingers in scene", siFatal);
	}
	f = GetValue("SelectionList");
	fix = ".chain.blendik";
	for (i=0;i<f.count;i++)
	{
		bone = (f(i) + fix);
		logmessage (bone);
		var ikfkexist = Dictionary.GetObject(bone, false);
		if (ikfkexist)
		{
		SetValue(bone, 0, null);
		}
	}
	DeselectAll();
}

